import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import ProductCard from '../components/ProductCard';
import { getFeaturedProducts, getProductCategories, getProducts } from '../services/api';
import { useTheme } from '../context/ThemeContext';

const HomeRebuild = () => {
  const { isDarkMode } = useTheme();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const search = searchParams.get('search') || '';
  const category = searchParams.get('category') || '';
  const [searchText, setSearchText] = useState('');
  const [featured, setFeatured] = useState([]);
  const [searchedProducts, setSearchedProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;

    const load = async () => {
      try {
        setLoading(true);
        const [featuredRes, categoriesRes] = await Promise.all([
          getFeaturedProducts(),
          getProductCategories()
        ]);
        if (!active) return;
        setFeatured(Array.isArray(featuredRes.data) ? featuredRes.data : []);
        setCategories(Array.isArray(categoriesRes.data) ? categoriesRes.data : []);
      } catch (error) {
        if (!active) return;
        setFeatured([]);
        setCategories([]);
      } finally {
        if (active) setLoading(false);
      }
    };

    load();
    return () => {
      active = false;
    };
  }, []);

  const quickCategories = useMemo(() => categories.slice(0, 8), [categories]);
  const hasFilters = Boolean(search.trim() || category);

  useEffect(() => {
    setSearchText(search);
  }, [search]);

  useEffect(() => {
    let active = true;

    const loadFiltered = async () => {
      if (!hasFilters) {
        setSearchedProducts([]);
        return;
      }
      try {
        setLoading(true);
        const res = await getProducts({ search: search.trim(), category, sort: 'rating_desc', limit: 40 });
        if (!active) return;
        setSearchedProducts(Array.isArray(res.data?.products) ? res.data.products : []);
      } catch (error) {
        if (!active) return;
        setSearchedProducts([]);
      } finally {
        if (active) setLoading(false);
      }
    };

    loadFiltered();
    return () => {
      active = false;
    };
  }, [hasFilters, search, category]);

  const handleSearch = (e) => {
    e.preventDefault();
    const value = searchText.trim();
    const params = new URLSearchParams(searchParams);
    if (value) {
      params.set('search', value);
    } else {
      params.delete('search');
    }
    setSearchParams(params);
  };

  return (
    <div className="space-y-8">
      <section className={`rounded-2xl border p-6 md:p-8 ${isDarkMode ? 'bg-gray-900 border-white/10 text-white' : 'bg-white border-gray-200 text-gray-900'}`}>
        <h1 className="text-3xl md:text-4xl font-extrabold">Rebuilding</h1>
        <p className={`mt-2 text-sm md:text-base ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
          Pehel blueprint banaenge uske baad. Tab tak search-first shopping flow live hai.
        </p>

        <form onSubmit={handleSearch} className="mt-5 flex flex-col md:flex-row gap-3">
          <input
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
            placeholder="Search product name..."
            className={`flex-1 rounded-xl border px-4 py-3 outline-none ${isDarkMode ? 'bg-black border-white/10 text-white placeholder:text-gray-500' : 'bg-white border-gray-300 text-gray-900 placeholder:text-gray-500'}`}
          />
          <button type="submit" className="rounded-xl px-6 py-3 font-semibold bg-yellow-400 hover:bg-yellow-500 text-gray-900">
            Search Products
          </button>
        </form>
      </section>

      {quickCategories.length > 0 ? (
        <section>
          <h2 className={`text-xl font-bold mb-3 ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Popular Categories</h2>
          <div className="flex flex-wrap gap-2">
            {quickCategories.map((cat) => (
              <button
                key={cat}
                type="button"
                onClick={() => {
                  const params = new URLSearchParams(searchParams);
                  params.set('category', cat);
                  setSearchParams(params);
                }}
                className={`px-4 py-2 rounded-xl border text-sm font-semibold ${isDarkMode ? 'border-white/10 text-gray-200 hover:bg-white/10' : 'border-gray-300 text-gray-700 hover:bg-gray-100'}`}
              >
                {cat}
              </button>
            ))}
          </div>
        </section>
      ) : null}

      <section>
        <div className="flex items-center justify-between mb-3">
          <h2 className={`text-xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Home Highlights</h2>
          <button type="button" onClick={() => navigate('/')} className="text-sm font-semibold text-blue-600">Reset</button>
        </div>

        {loading ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className={`h-64 rounded-xl animate-pulse ${isDarkMode ? 'bg-white/10' : 'bg-gray-200'}`} />
            ))}
          </div>
        ) : hasFilters ? (
          searchedProducts.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              {searchedProducts.map((product, idx) => (
                <ProductCard key={product._id || idx} product={product} index={idx} />
              ))}
            </div>
          ) : (
            <div className={`rounded-xl border p-6 text-center ${isDarkMode ? 'border-white/10 text-gray-300' : 'border-gray-200 text-gray-600'}`}>
              Koi product nahi mila.
            </div>
          )
        ) : featured.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {featured.slice(0, 8).map((product, idx) => (
              <ProductCard key={product._id || idx} product={product} index={idx} />
            ))}
          </div>
        ) : (
          <div className={`rounded-xl border p-6 text-center ${isDarkMode ? 'border-white/10 text-gray-300' : 'border-gray-200 text-gray-600'}`}>
            Products abhi empty hain. Naye products add hone ke baad yahan show honge.
          </div>
        )}
      </section>
    </div>
  );
};

export default HomeRebuild;
